suppressMessages({library(dplyr);library(tidyr)})
r <- readRDS("data/federal_elections/wahlkreis_level/final/federal_wkr_2021_on_2025.rds")
cw <- readRDS("data/federal_elections/wahlkreis_level/final/wkr_2021_to_2025_crosswalk.rds")
w <- readRDS("data/federal_elections/wahlkreis_level/final/federal_wkr_unharm.rds")
print(table(cw$boundary_change)); print(table(cw$renamed)); print(table(r$boundary_change,r$stimme))
cat("dup:",sum(duplicated(r[,c("wkr_nr","stimme")])),"\n")
print(r %>% group_by(stimme) %>% summarise(elig=sum(eligible_voters), valid=sum(valid_votes), spd=round(sum(spd*valid_votes,na.rm=T)), cdu=round(sum(cdu*valid_votes,na.rm=T)), afd=round(sum(afd*valid_votes,na.rm=T))) %>% as.data.frame)
pc <- names(r)[which(names(r)=="afd"):which(names(r)=="cdu_csu")]
r$sh <- rowSums(r[,setdiff(pc,"cdu_csu")],na.rm=T); print(summary(r$sh))
cat("cdu_csu check: ", max(abs(r$cdu_csu - rowSums(r[,c("cdu","csu")],na.rm=T))),"\n")
# unchanged WKRs should equal 2021 actual (wkr file) 
a <- w %>% filter(election_year==2021) %>% select(wkr_nr,stimme,eligible_voters,valid_votes,spd,cdu,csu,afd)
j <- r %>% filter(boundary_change=="unchanged") %>% inner_join(a,by=c("wkr_nr","stimme"),suffix=c(".r",".a"))
cat("unchanged n:",nrow(j),"\n")
print(j %>% summarise(dE=max(abs(eligible_voters.r-eligible_voters.a)), dV=max(abs(valid_votes.r-valid_votes.a)), dspd=max(abs(spd.r*valid_votes.r-spd.a*valid_votes.a),na.rm=T)))
print(j %>% filter(abs(valid_votes.r-valid_votes.a)>0) %>% select(wkr_nr,wkr_name,stimme,valid_votes.r,valid_votes.a) %>% head(10) %>% as.data.frame)
print(cw %>% filter(boundary_change!="new") %>% summarise(n=n(), mx=max(abs(eligible_delta),na.rm=T)))
print(cw %>% filter(boundary_change=="unchanged", eligible_delta!=0) %>% select(wkr_nr,wkr_name,recomputed_2021_eligible,actual_2021_eligible,eligible_delta) %>% as.data.frame)
print(cw %>% filter(boundary_change=="redrawn") %>% summarise(n=n(), tot_rec=sum(recomputed_2021_eligible), tot_act=sum(actual_2021_eligible,na.rm=T)))
print(cw %>% summarise(rec=sum(recomputed_2021_eligible,na.rm=T), act=sum(actual_2021_eligible,na.rm=T)))
cat("r total elig:", sum(r$eligible_voters[r$stimme=="erststimme"]), " 2021 actual wkr total:", sum(a$eligible_voters[a$stimme=="erststimme"]), "\n")
print(cw %>% filter(is.na(prior_2021_wkr_nr)|boundary_change=="new") %>% as.data.frame)
print(cw %>% filter(boundary_change=="redrawn") %>% select(wkr_nr,wkr_name,prior_2021_wkr_nr,recomputed_2021_eligible,actual_2021_eligible,eligible_delta) %>% head(40) %>% as.data.frame)
